package com.rikkeibank.customer.service; import com.rikkeibank.common.api.BusinessException;import com.rikkeibank.customer.domain.Customer;import com.rikkeibank.customer.repo.CustomerRepository;import org.springframework.cache.annotation.*;import org.springframework.data.domain.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.time.LocalDate;import java.util.UUID;
@Service public class CustomerService{private final CustomerRepository repo;public CustomerService(CustomerRepository r){repo=r;}@Transactional @CachePut(value="customers",key="#result.id") public Customer create(String n,String e,String p,String nid,LocalDate d,String a){if(repo.existsByEmail(e)||repo.existsByNationalId(nid))throw BusinessException.conflict("CUSTOMER_EXISTS","Email or national ID already exists");return repo.save(new Customer(n,e,p,nid,d,a));}@Cacheable(value="customers",key="#id")public Customer get(UUID id){return repo.findById(id).orElseThrow(()->BusinessException.notFound("Customer not found"));}public Page<Customer> list(Pageable p){return repo.findAll(p);}@Transactional @CachePut(value="customers",key="#id")public Customer update(UUID id,String n,String e,String p,String nid,LocalDate d,String a,boolean active){Customer c=get(id);c.update(n,e,p,nid,d,a,active);return c;}@Transactional @CacheEvict(value="customers",key="#id")public void delete(UUID id){if(!repo.existsById(id))throw BusinessException.notFound("Customer not found");repo.deleteById(id);}}

